```javascript
const fs = require('fs');

let raw = '';
try {
  raw = fs.readFileSync('/dev/stdin', 'utf8');
} catch (e) {
  raw = fs.readFileSync(0, 'utf8');
}

const trimmed = raw.trim();
if (!trimmed) {
  console.log(0);
} else {
  const toks = trimmed.split(/\s+/).map(Number);
  const n = toks[0];
  const v = toks.slice(1, 1 + n);

  // Comprime valores em ids e guarda posicoes de ocorrencia
  const idOf = new Map();
  const occ = [];
  const ids = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    let id = idOf.get(v[i]);
    if (id === undefined) {
      id = occ.length;
      idOf.set(v[i], id);
      occ.push([]);
    }
    ids[i] = id;
    occ[id].push(i);
  }
  const D = occ.length;   // quantidade de valores distintos
  const INF = n;          // sentinela (posicoes validas sao < n)

  // nx[id][i] = menor j > i com ids[j] === id, ou INF se nao existe
  const nx = new Array(D);
  for (let id = 0; id < D; id++) {
    const arr = new Int32Array(n);
    let last = INF;
    for (let i = n - 1; i >= 0; i--) {
      arr[i] = last;
      if (ids[i] === id) last = i;
    }
    nx[id] = arr;
  }

  // Ideia: fixando o par de valores {a,b}, a melhor subsequencia marcada
  // tem tamanho igual ao numero de "runs" (blocos maximais) apos filtrar
  // a sequencia original mantendo apenas a e b (de cada run sai no maximo 1).
  // O numero de runs = 1 + (transicoes a->b) + (transicoes b->a), onde uma
  // transicao a->b ocorre em uma ocorrencia p de a sse a proxima ocorrencia
  // de b apos p vem antes da proxima ocorrencia de a apos p.
  let ans = 1;
  for (let a = 0; a < D; a++) {
    const occA = occ[a];
    const nxA = nx[a];
    const la = occA.length;
    for (let b = a + 1; b < D; b++) {
      const occB = occ[b];
      const nxB = nx[b];
      const lb = occB.length;
      let t = 0;
      for (let i = 0; i < la; i++) {
        const p = occA[i];
        const nxtA = i + 1 < la ? occA[i + 1] : INF;
        if (nxB[p] < nxtA) t++;
      }
      for (let i = 0; i < lb; i++) {
        const p = occB[i];
        const nxtB = i + 1 < lb ? occB[i + 1] : INF;
        if (nxA[p] < nxtB) t++;
      }
      const f = 1 + t;
      if (f > ans) ans = f;
    }
  }

  console.log(ans);
}
